insert into cards (company_id, card_key, format, title, angle, evidence, tags, sources, sort_order)
select id, 'vvs-03', 'long_form', 'Meta VR Glasses: Port or Rebuild?', 'Meta announced VR Glasses on Sept 23, 2026 at $1,299 for spring 2027, with the Quest OS and app store. One trade summary says Quest training content should run, but controller-based or peripheral-vision modules may need rework.', 'Your blog already covers Meta Quest onboarding (Immersive Exposure), hazard recognition architecture and Android XR versus Vision Pro versus Quest. A post-Connect port checklist extends that coverage. The summary is a vendor blog, so verify against Meta''s developer documentation.', '{meta-vr-glasses,long-form,porting}'::text[], '[{"title": "Meta VR Glasses", "publisher": "Road to VR", "url": "https://roadtovr.com/meta-vr-glasses-unveiled-price-release-date/"}, {"title": "enterprise training", "publisher": "VR Vision Group", "url": "https://www.vrvisiongroup.com/meta-vr-glasses-enterprise-training/"}, {"title": "blog index", "publisher": "Virtual Verse Studio", "url": "https://virtualverse.studio/blogs"}]'::jsonb, 2 from companies where slug = 'virtualverse-w9eg79'
